SELECT CAST(ROUND(CASE WHEN SUM("PARTIAL_stat_cnt_0") = 1 THEN 0 ELSE (SUM("PARTIAL_stat_m2_0") + SUM("PARTIAL_stat_cnt_0" * ("PARTIAL_stat_mean_0" - "STAT_GMEAN_0") * ("PARTIAL_stat_mean_0" - "STAT_GMEAN_0"))) / (SUM("PARTIAL_stat_cnt_0") - 1) END, 4) AS DECIMAL(36,4)) FROM (SELECT q.*, "STAT_REF_0" + SUM("PARTIAL_stat_cnt_0" * ("PARTIAL_stat_mean_0" - "STAT_REF_0")) OVER () / NULLIF(SUM("PARTIAL_stat_cnt_0") OVER (), 0) AS "STAT_GMEAN_0" FROM (SELECT p.*, MIN("PARTIAL_stat_mean_0") OVER () AS "STAT_REF_0" FROM (SELECT LAKEHOUSE_SCAN('{"table_root":"s3://warehouse/db/events","projection":[],"aggregates":[{"kind":"variance","column":"AMOUNT"}],"storage":{"connection":{"name":"LAKEHOUSE_CATALOG_CREDS","allow_http":true}},"df_target_partitions":4,"df_batch_size":8192,"df_threads_per_udf":2,"memory_pool_fraction":0.6,"instance_overhead_mb":200,"s3_max_connections":8}', files) EMITS ("PARTIAL_stat_cnt_0" DECIMAL(20,0), "PARTIAL_stat_mean_0" DOUBLE PRECISION, "PARTIAL_stat_m2_0" DOUBLE PRECISION) FROM (SELECT LAKEHOUSE_DISTRIBUTE_FILES(files) FROM (VALUES (0,'[["data/part-0.parquet",1000]]'),(1,'[["data/part-1.parquet",2000]]'),(2,'[["data/part-2.parquet",1500]]')) AS shards(shard_key, files) GROUP BY shard_key)) p) q)